from pathlib import Path
import json,sys
root=Path(__file__).resolve().parents[1]
rows=json.loads((root/'artifacts/ship-detail/manifest.json').read_text(encoding='utf8'))['ships']
p=Path(sys.argv[1]);s=p.read_text(encoding='utf8')
options=''.join(f'<option value="{r["slug"]}">{r["name"]} / {r["size"]}</option>' for r in rows)
controls='''<style>body{background:#050b13!important}#ship-review{position:fixed;top:16px;left:24px;right:24px;z-index:10;color:#d5e8ee;font:15px system-ui;background:#0b1a28dd;border:1px solid #294757;border-radius:12px;padding:16px}#ship-review select,#ship-review button{font:inherit;color:#d9edf6;background:#173748;border:1px solid #436374;border-radius:6px;padding:8px;margin:4px}#ship-review p{margin:5px;color:#8da8b7;font-size:12px}</style><div id="ship-review"><strong>GALAXY / SHIP DETAIL REVIEW</strong><p>Native Defold render. Models normalized for inspection; gameplay sizes are unchanged.</p><select aria-label="Ship">'''+options+'''</select><button data-command="original">Original</button><button data-command="detail">Detailed</button><button data-command="recolor">Solar Regatta skin</button><button data-command="rear">Rear / engines</button><button data-command="front">Front</button><button data-command="rotate">Rotate / pause</button><span id="variant">Detailed</span><p id="rendered">Loading model...</p></div><script>document.querySelector('#ship-review select').onchange=e=>window.galaxyShipCommand=e.target.value;document.querySelectorAll('[data-command]').forEach(b=>b.onclick=()=>{window.galaxyShipCommand=b.dataset.command;if(['original','detail','recolor'].includes(b.dataset.command))document.getElementById('variant').textContent=b.textContent;});</script>'''
if 'id="ship-review"' not in s:p.write_text(s.replace('</body>',controls+'</body>'),encoding='utf8')
